def unitpicker(a, llim=0.1, denominator=None, focus_stage=None):
    if not isinstance(a,(int,float)):
        a = nominal_values(a)
    a = np.percentile(a[~np.isnan(a)],25)
    if denominator is not None:
        pd = pretty_element(denominator)
    else:
        pd = ''
    if focus_stage == 'calibrated':
        udict = {0:'mol/mol '+pd,1:'mmol/mol '+pd,2:'μmol/mol '+pd,3:'nmol/mol '+pd,4:'pmol/mol '+pd,5:'fmol/mol '+pd}
    elif focus_stage == 'ratios':
        udict = {0:'counts/count '+pd,1:'10^{-3} counts/count '+pd,2:'10^{-6} counts/count '+pd,3:'10^{-9} counts/count '+pd,4:'10^{-12} counts/count '+pd,5:'10^{-15} counts/count '+pd}
    elif focus_stage in ('rawdata','despiked','bkgsub'):
        udict = {0:'counts',1:'10^{-3} counts',2:'10^{-6} counts',3:'10^{-9} counts',4:'10^{-12} counts',5:'10^{-15} counts'}
    else:
        udict = {0:'',1:'',2:'',3:'',4:'',5:''}
    a = abs(a)
    n = 0
    if a < llim:
        while a < llim:
            a *= 1000
            n += 1
